function Top($lesson,$title){@"
<div style="font-family: Arial, Helvetica, sans-serif; font-size: 18px; line-height: 1.75; color: #ffffff; max-width: 980px; margin: 0 auto 18px auto; display: flex; justify-content: space-between; align-items: center; gap: 16px; background: #111827; border-radius: 12px; padding: 14px 18px; box-shadow: 0 4px 14px rgba(17,24,39,0.18);"><div style="font-size: 0.95rem; font-weight: 700; letter-spacing: 0.02em;">ALG2 | Unit 03 | Lesson $lesson</div></div>
<div style="font-family: Arial, Helvetica, sans-serif; font-size: 18px; line-height: 1.75; color: #1f2933; max-width: 980px; margin: 0 auto 22px auto; background: #e8f4ff; border-left: 8px solid #2563eb; border-radius: 10px; padding: 24px;"><h1 style="font-size: 30px; margin-top: 0; margin-bottom: 12px;">$title</h1></div>
"@}
function Card($bg,$border,$title,$body){@"
<div style="font-family: Arial, Helvetica, sans-serif; font-size: 18px; line-height: 1.75; color: #1f2933; max-width: 980px; margin: 0 auto 22px auto; border: 1px solid #d1d5db; border-radius: 10px; padding: 22px; background: $bg; border-left: 6px solid $border;"><h2 style="font-size: 24px; margin-top: 0; margin-bottom: 10px;">$title</h2>
$body
</div>
"@}
function WritePage($dir,$file,$content){Set-Content -LiteralPath (Join-Path $dir $file) -Value $content -Encoding UTF8}
function Item($id,$std,$prompt,$correct,$cfb,$wrongs,$pos){
  $choices=New-Object System.Collections.Generic.List[object]
  for($i=0;$i -lt $wrongs.Count;$i+=2){$choices.Add([pscustomobject]@{C=$false;A=$wrongs[$i];F=$wrongs[$i+1]})}
  $choices.Insert($pos,[pscustomobject]@{C=$true;A=$correct;F=("Correct. "+$cfb)})
  [pscustomobject]@{Id=$id;Std=$std;Prompt=$prompt;Choices=$choices}
}
function Make($prefix,$std,$specs,$gp){
  $items=New-Object System.Collections.Generic.List[object]
  for($i=0;$i -lt $specs.Count;$i++){
    $id=if($gp){"{0}{1:D2}" -f $prefix,($i+1)}else{"{0}_Q{1:D2}" -f $prefix,($i+1)}
    $s=$specs[$i]; $items.Add((Item $id $std $s[0] $s[1] $s[2] $s[3] ($i%4)))
  }
  $items
}
function Gift($path,$items){
  $out=New-Object System.Collections.Generic.List[string]
  foreach($it in $items){
    $out.Add("::$($it.Id)::")
    $out.Add("Question ID:<br>$($it.Id)<br><br>MLA Standard:<br>$($it.Std)<br><br>Question:<br>$($it.Prompt) {")
    foreach($ch in $it.Choices){$out.Add(($(if($ch.C){"="}else{"~"})+" $($ch.A)#$($ch.F)"))}
    $out.Add("}");$out.Add("")
  }
  Set-Content -LiteralPath $path -Value ($out -join "`n") -Encoding UTF8
}
function JsonLesson($dir,$lesson,$title,$std,$desc,$bench,$gp,$quiz,$bank,$per){
  $pages=@("P01","P02","P03","P04","P05","P06","P07"|ForEach-Object{@{title=$_;id=$_;file="$_.html"}})
  @{course="ALG2";assessment="Quiz";guidedPractice=@{questionCount=5;graded=$false;file=$gp;feedback="immediate"};masteryThreshold=80;primaryStandards=@(@{code=$std;description=$desc;floridaBenchmark=$bench});pages=$pages;lesson=$lesson;title=$title;unit="Unit 03";quiz=@{attemptPolicy="one_attempt_then_TOR_intervention_if_below_80";randomizedRetakeRequired=$true;questionBank=$true;questionsPerAttempt=$per;bankSize=$bank;file=$quiz}}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $dir "lesson.json") -Encoding UTF8
}
function JsonQuiz($dir,$lesson,$title,$std,$desc,$bench,$file,$bank,$per,$dist){
  @{course="ALG2";unit="Unit 03";lesson=$lesson;title=$title;primaryStandard=@{code=$std;description=$desc;floridaBenchmark=$bench};format="GIFT";giftFile=$file;questionBankSize=$bank;questionsPerAttempt=$per;masteryThreshold=80;attemptPolicy=@{studentAttemptsBeforeIntervention=1;belowMasteryAction="Teacher of Record intervention and release of another randomized attempt.";questionReuseRule="Questions must not repeat exactly across attempts."};correctAnswerDistribution=$dist}|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $dir "quiz.json") -Encoding UTF8
}

