$pages7=@{
P01=(Top "07" "P01 Lesson Overview")+(Card "#fffbeb" "#f59e0b" "Lesson Title" '<p style="margin-bottom: 14px;"><strong>Lesson 7: Rational Functions and Applications</strong></p><p style="margin-bottom: 14px;">Analyze rational function behavior and model contexts involving rational relationships.</p>')+(Card "#f8fafc" "#64748b" "Standards Covered in This Lesson" '<p style="margin-bottom: 14px;"><strong>MLA.A2.RR.5; MLA.A2.RR.6</strong></p><p style="margin-bottom: 14px;"><strong>Florida B.E.S.T. Benchmark:</strong> MA.912.AR.8.2; MA.912.AR.8.3</p><p style="margin-bottom: 14px;">Analyze rational function graphs, restrictions, asymptotes, and contextual meaning.</p>')+(Card "#ecfdf5" "#059669" "What You Will Learn" '<ul style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Identify domain restrictions and vertical asymptotes of rational functions.</li><li style="margin-bottom: 8px;">Interpret horizontal asymptotes and end behavior.</li><li style="margin-bottom: 8px;">Connect rational function features to real-world contexts.</li><li style="margin-bottom: 8px;">Use graph features to describe rational relationships.</li></ul>')+(Card "#fff7ed" "#ea580c" "What You Will Do" '<ul style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Take notes on rational function features.</li><li style="margin-bottom: 8px;">Study worked examples with asymptotes, intercepts, and context restrictions.</li><li style="margin-bottom: 8px;">Complete guided practice, independent work, checkpoint, notebook evidence, and a lesson quiz.</li></ul>')+(Card "#fef2f2" "#dc2626" "How You Will Show Mastery" '<ul style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Identify rational function domain restrictions.</li><li style="margin-bottom: 8px;">Describe asymptotes and graph behavior accurately.</li><li style="margin-bottom: 8px;">Interpret rational model features in context.</li></ul>')+(Card "#f5f3ff" "#7c3aed" "Student-Friendly Standard Connection" '<p style="margin-bottom: 14px;"><strong>MLA.A2.RR.5; MLA.A2.RR.6:</strong> Analyze rational functions and applications.</p><p style="margin-bottom: 14px;">In student language: <strong>I can read a rational function graph or model and explain its restrictions, asymptotes, and meaning.</strong></p>')
P02=(Top "07" "P02 Notebook Task Part 1")+(Card "#fffbeb" "#f59e0b" "Notebook Setup" '<p style="margin-bottom: 14px;">Title your notes: <strong>Lesson 7: Rational Functions and Applications</strong>.</p><p style="margin-bottom: 14px;">Write the standard: <strong>MLA.A2.RR.5; MLA.A2.RR.6</strong>.</p>')+(Card "#f8fafc" "#64748b" "Key Vocabulary" '<ul style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Vertical asymptote: a vertical line the graph approaches near a restricted input.</li><li style="margin-bottom: 8px;">Horizontal asymptote: a horizontal line the graph approaches as x becomes very large or very small.</li><li style="margin-bottom: 8px;">Hole: a removable discontinuity caused by a canceled factor.</li><li style="margin-bottom: 8px;">Rational model: a context modeled by a ratio of expressions.</li></ul>')+(Card "#ecfdf5" "#059669" "Correct Example" '<div style="background: #dcfce7; border: 2px solid #16a34a; border-radius: 10px; padding: 16px;"><strong>Correct:</strong> f(x) = 1/(x - 3) has vertical asymptote x = 3 because the denominator is zero there.</div>')+(Card "#fef2f2" "#dc2626" "Incorrect Example" '<div style="background: #fee2e2; border: 2px solid #dc2626; border-radius: 10px; padding: 16px;"><strong>Incorrect:</strong> Saying f(x) = 1/(x - 3) has vertical asymptote x = -3 is incorrect because x - 3 = 0 gives x = 3.</div>')
P03=(Top "07" "P03 Notebook Task Part 2")+(Card "#fffbeb" "#f59e0b" "Notebook Task" '<ol style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">List denominator restrictions for each rational function.</li><li style="margin-bottom: 8px;">Label vertical and horizontal asymptotes.</li><li style="margin-bottom: 8px;">Explain what a restriction means in a real-world context.</li></ol>')+(Card "#ecfdf5" "#059669" "Correct Reasoning" '<div style="background: #dcfce7; border: 2px solid #16a34a; border-radius: 10px; padding: 16px;"><strong>Correct:</strong> For f(x) = 2/(x + 4), the vertical asymptote is x = -4, not x = 4.</div>')+(Card "#fef2f2" "#dc2626" "Common Mistake" '<div style="background: #fee2e2; border: 2px solid #dc2626; border-radius: 10px; padding: 16px;"><strong>Incorrect:</strong> Treating a restricted input as a normal output point is incorrect because the function is undefined there.</div>')
P04=(Top "07" "P04 Concept Instruction / Worked Examples")+(Card "#f8fafc" "#64748b" "Concept Instruction" '<p style="margin-bottom: 14px;">Rational functions often have restrictions and asymptotes. The denominator identifies values that are not allowed. A non-canceled denominator factor usually creates a vertical asymptote. Horizontal asymptotes describe long-run behavior.</p>')+(Card "#ecfdf5" "#059669" "Worked Examples" '<p style="margin-bottom: 14px;"><strong>Example 1:</strong> f(x) = 3/(x - 2) has domain x &ne; 2 and vertical asymptote x = 2.</p><p style="margin-bottom: 14px;"><strong>Example 2:</strong> f(x) = (2x + 1)/(x - 4) has vertical asymptote x = 4 and horizontal asymptote y = 2 because the leading coefficient ratio is 2/1.</p><p style="margin-bottom: 14px;"><strong>Example 3:</strong> If T(n) = 120/n gives time per worker for a fixed job, n = 0 is not allowed because zero workers cannot complete the job.</p>')+(Card "#ecfdf5" "#059669" "Correct Reasoning Check" '<div style="background: #dcfce7; border: 2px solid #16a34a; border-radius: 10px; padding: 16px;"><strong>Correct:</strong> In a model, restrictions must make sense algebraically and contextually.</div>')+(Card "#fef2f2" "#dc2626" "Common Mistake" '<div style="background: #fee2e2; border: 2px solid #dc2626; border-radius: 10px; padding: 16px;"><strong>Incorrect:</strong> Using x = 0 in f(x) = 5/x is incorrect because division by zero is undefined.</div>')
P05=(Top "07" "P05 Guided Practice")+(Card "#fffbeb" "#f59e0b" "Guided Practice" '<p style="margin-bottom: 14px;">Complete the guided practice in Moodle. Identify restrictions and asymptotes before interpreting the graph or context.</p>')+(Card "#ecfdf5" "#059669" "Before You Submit" '<ul style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Set denominator factors equal to zero to find restrictions.</li><li style="margin-bottom: 8px;">Use leading terms to identify horizontal asymptotes when appropriate.</li><li style="margin-bottom: 8px;">Check whether the context allows the input value.</li></ul>')
P06=(Top "07" "P06 Independent Work + Checkpoint Submission + Notebook Evidence Submission")+(Card "#f8fafc" "#64748b" "Independent Work" '<ol style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Find the domain and vertical asymptote of f(x) = 4/(x - 5).</li><li style="margin-bottom: 8px;">Find the horizontal asymptote of g(x) = (3x + 2)/(x - 1).</li><li style="margin-bottom: 8px;">Explain why x = 0 is not allowed in h(x) = 10/x.</li><li style="margin-bottom: 8px;">Interpret T(n) = 60/n for n workers.</li><li style="margin-bottom: 8px;">Describe one difference between a vertical asymptote and a horizontal asymptote.</li></ol>')+(Card "#fff7ed" "#ea580c" "Checkpoint Submission" '<p style="margin-bottom: 14px;">Submit one rational function analysis that includes domain restrictions, vertical asymptote, horizontal behavior, and one context interpretation.</p>')+(Card "#f5f3ff" "#7c3aed" "Notebook Evidence Submission" '<p style="margin-bottom: 14px;">Submit notebook evidence showing vocabulary, worked examples, corrected mistakes, independent work, and checkpoint reasoning.</p>')
P07=(Top "07" "P07 Lesson Quiz")+(Card "#fffbeb" "#f59e0b" "Lesson Quiz" '<p style="margin-bottom: 14px;">Complete the lesson quiz in Moodle after finishing notebook work, guided practice, independent work, and checkpoint submission.</p><p style="margin-bottom: 14px;">Use restrictions, asymptotes, and context meaning carefully.</p>')+(Card "#ecfdf5" "#059669" "Quiz Expectations" '<ul style="padding-left: 26px; margin-bottom: 16px;"><li style="margin-bottom: 8px;">Identify restricted inputs.</li><li style="margin-bottom: 8px;">Interpret vertical and horizontal asymptotes.</li><li style="margin-bottom: 8px;">Connect rational model features to context.</li><li style="margin-bottom: 8px;">Demonstrate at least 80% mastery or complete Teacher of Record intervention before another randomized attempt is released.</li></ul>')
}

